/**
 * Official Andhra Pradesh Mandal-Wise Cumulative Monsoon Rainfall Dataset
 * Period: 01/06/2025 to 13/10/2026 (APWRIMS & IMD Hydro-Meteorological Telemetry Grid)
 * 
 * Sourced directly from State Hydrological Surveillance Portal across all districts & mandals.
 * Status Definitions:
 * - Large Excess: Departure >= +60%
 * - Excess: Departure +20% to +59%
 * - Normal: Departure -19% to +19%
 * - Deficient: Departure -59% to -20%
 * - Large Deficient: Departure -99% to -60%
 * - No Rain: Departure -100%
 */

import { HydrologicalStation } from './indiaHydrologyData';

export type MandalRainfallStatus = 
  | 'Large Excess'
  | 'Excess'
  | 'Normal'
  | 'Deficient'
  | 'Large Deficient'
  | 'No Rain';

export interface APMandalRainfallRecord {
  id: string;
  sno: number;
  district: string;
  mandal: string;
  actualMm: number;
  normalMm: number;
  deviationPercent: number;
  status: MandalRainfallStatus;
  lat: number;
  lng: number;
  period: string;
}

export interface APDistrictRainfallSummary {
  district: string;
  largeExcess: number;
  excess: number;
  normal: number;
  deficient: number;
  largeDeficient: number;
  noRain: number;
  totalMandals: number;
  avgActualMm: number;
  avgNormalMm: number;
  avgDeviationPercent: number;
}

