export const AP_MANDAL_RAINFALL_STATIONS: HydrologicalStation[] = AP_MANDAL_WISE_RAINFALL_2026.map((r) => {
  const isNormal = r.status === 'Normal';
  const isExcess = r.status === 'Large Excess' || r.status === 'Excess';
  const isLargeDeficient = r.status === 'Large Deficient';

  const statusColor: 'green' | 'blue' | 'yellow' | 'red' = 
    isNormal ? 'green' :
    isExcess ? 'blue' :
    isLargeDeficient ? 'red' : 'yellow';

  return {
    id: r.id,
    name: `${r.mandal} Mandal Telemetry`,
    code: `AP-MNDL-${r.id.substring(r.id.length - 8).toUpperCase()}`,
    category: 'rainfall',
    state: 'Andhra Pradesh',
    district: r.district,
    mandal: r.mandal,
    basin: `${r.district} Hydrological Basin`,
    agency: 'IMD',
    lat: r.lat,
    lng: r.lng,
    status: statusColor,
    statusLabel: `${r.actualMm} mm (Norm: ${r.normalMm} mm | ${r.deviationPercent}%)`,
    lastUpdated: '13-10-2026 08:30 IST',
    rainfallMm: r.actualMm,
    normalRainfallMm: r.normalMm,
    departurePercent: r.deviationPercent,
    notes: `Cumulative Monsoon (01/06/2025 to 13/10/2026): Actual ${r.actualMm} mm vs Normal ${r.normalMm} mm. Deviation: ${r.deviationPercent}%. Status: ${r.status}.`,
    governmentDossier: {
      type: 'Mandal-Wise Rainfall Telemetry',
      period: '01/06/2025 to 13/10/2026',
      status: r.status,
      cumulative: {
        actualMm: r.actualMm,
        normalMm: r.normalMm,
        departure: r.deviationPercent,
      },
    },
  };
});
